package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)

	var first, sec string
	fmt.Fscan(in, &first, &sec)

	var n int
	fmt.Fscan(in, &n)

	for i := n; i > 1; i-- {
		if n-4 >= 1 {
			n = n - 4
		} else {
			break
		}
	}

	all := "<^>v"
	start := 0
	end := 0

	for i := 0; i < len(all); i++ {
		if first[0] == all[i] {
			start = i
		}
		if sec[0] == all[i] {
			end = i
		}
	}

	if start == end || start == end-2 || start == end+2 {
		fmt.Println("undefined")
	} else {
		if (start == end-1 && n == 1) || (start == end+3 && n == 1) || (start == end-3 && n != 1) || (start == end+1 && n != 1) {
			fmt.Println("cw")
		} else if (start == end-3 && n == 1) || (start == end+1 && n == 1) || (start == end-1 && n != 1) || (start == end+3 && n != 1) {
			fmt.Println("ccw")
		}
	}
}

